import React, { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Menu, X, Phone, Sparkles } from "lucide-react";
import { BRAND } from "../types";

const navLinks = [
  { label: "Home", href: "#top" },
  { label: "About", href: "#about" },
  { label: "Collections", href: "#collections" },
  { label: "Reviews", href: "#reviews" },
  { label: "Contact", href: "#contact" },
];

export default function Navbar({ onOpenQuote }: { onOpenQuote: () => void }) {
  const [scrolled, setScrolled] = useState(false);
  const [open, setOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 50);
    window.addEventListener("scroll", handleScroll, { passive: true });
    handleScroll();
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  return (
    <>
      <motion.header
        className={`fixed top-0 left-0 right-0 z-50 transition-all duration-500 ${
          scrolled ? "bg-white/95 backdrop-blur-xl shadow-xl" : "bg-transparent"
        }`}
        initial={{ y: -100 }}
        animate={{ y: 0 }}
        transition={{ duration: 0.6, ease: "easeOut" }}
      >
        <div className="container mx-auto px-6">
          <div className="flex items-center justify-between h-20">
            <motion.a
              href="#top"
              className="flex items-center"
              whileHover={{ scale: 1.02 }}
              onClick={(e) => { e.preventDefault(); document.getElementById("top")?.scrollIntoView({ behavior: "smooth" }); }}
            >
              <span className="text-xl font-bold tracking-wider text-amber-400">
                D SAJAWAT
              </span>
            </motion.a>

            <nav className="hidden lg:flex items-center gap-10">
              {navLinks.map((link, i) => (
                <motion.a
                  key={link.href}
                  href={link.href}
                  className={`text-sm font-medium transition-colors relative group ${
                    scrolled ? "text-gray-800 hover:text-amber-500" : "text-white/90 hover:text-white"
                  }`}
                  initial={{ opacity: 0, y: -20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: i * 0.1 }}
                  onClick={(e) => { e.preventDefault(); document.querySelector(link.href)?.scrollIntoView({ behavior: "smooth" }); }}
                >
                  {link.label}
                  <span className="absolute -bottom-1 left-0 w-0 h-0.5 bg-amber-400 transition-all group-hover:w-full" />
                </motion.a>
              ))}
            </nav>

            <div className="hidden lg:flex items-center gap-5">
              <motion.a
                href={`tel:${BRAND.phones[0]}`}
                className={`flex items-center gap-2 text-sm font-medium ${scrolled ? "text-amber-500" : "text-white"}`}
                whileHover={{ scale: 1.05 }}
              >
                <Phone size={16} />
                <span>Call Now</span>
              </motion.a>
              <motion.button
                onClick={onOpenQuote}
                className="px-6 py-2.5 bg-gradient-to-r from-amber-400 to-amber-500 text-white font-semibold text-sm rounded-full flex items-center gap-2 shadow-lg shadow-amber-500/25 hover:shadow-amber-500/40 transition-shadow"
                whileHover={{ scale: 1.05, boxShadow: "0 10px 40px rgba(212, 175, 55, 0.4)" }}
                whileTap={{ scale: 0.98 }}
              >
                <Sparkles size={16} />
                <span>Get Quote</span>
              </motion.button>
            </div>

            <motion.button
              className={`lg:hidden p-2 rounded-lg ${scrolled ? "text-gray-800" : "text-white"}`}
              onClick={() => setOpen(!open)}
              whileTap={{ scale: 0.95 }}
            >
              {open ? <X size={24} /> : <Menu size={24} />}
            </motion.button>
          </div>
        </div>
      </motion.header>

      <AnimatePresence>
        {open && (
          <>
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="fixed inset-0 bg-black/60 backdrop-blur-sm z-40 lg:hidden"
              onClick={() => setOpen(false)}
            />
            <motion.div
              initial={{ x: "100%" }}
              animate={{ x: 0 }}
              exit={{ x: "100%" }}
              transition={{ type: "spring", damping: 25, stiffness: 200 }}
              className="fixed top-0 right-0 bottom-0 w-[320px] max-w-[85vw] z-50 bg-white shadow-2xl"
            >
              <div className="flex flex-col h-full p-8">
                <div className="flex justify-end mb-8">
                  <motion.button onClick={() => setOpen(false)} className="p-2 text-gray-600" whileTap={{ scale: 0.95 }}>
                    <X size={24} />
                  </motion.button>
                </div>

                <nav className="flex flex-col gap-6 flex-1">
                  {navLinks.map((link, i) => (
                    <motion.a
                      key={link.href}
                      href={link.href}
                      className="text-2xl font-semibold text-gray-800 hover:text-amber-500 transition-colors"
                      style={{ fontFamily: "Georgia, serif" }}
                      initial={{ opacity: 0, x: 30 }}
                      animate={{ opacity: 1, x: 0 }}
                      transition={{ delay: i * 0.08 }}
                      onClick={(e) => {
                        e.preventDefault();
                        document.querySelector(link.href)?.scrollIntoView({ behavior: "smooth" });
                        setOpen(false);
                      }}
                    >
                      {link.label}
                    </motion.a>
                  ))}
                </nav>

                <div className="flex flex-col gap-4 pt-6 border-t border-gray-100">
                  <motion.a
                    href={`tel:${BRAND.phones[0]}`}
                    className="flex items-center justify-center gap-3 px-6 py-3 border-2 border-gray-200 rounded-full text-gray-700 font-medium"
                    whileHover={{ borderColor: "#d4af37", color: "#d4af37" }}
                  >
                    <Phone size={18} />
                    <span>Call Now</span>
                  </motion.a>
                  <motion.button
                    onClick={() => { setOpen(false); onOpenQuote(); }}
                    className="flex items-center justify-center gap-3 px-6 py-3 bg-gradient-to-r from-amber-400 to-amber-500 rounded-full text-white font-semibold shadow-lg"
                    whileHover={{ scale: 1.02 }}
                    whileTap={{ scale: 0.98 }}
                  >
                    <Sparkles size={18} />
                    <span>Get Quote</span>
                  </motion.button>
                </div>
              </div>
            </motion.div>
          </>
        )}
      </AnimatePresence>
    </>
  );
}
